create table if not exists public.smartvibe_signal_outcomes (signal_id uuid primary key references public.signals(id) on delete cascade, status text not null check(status in ('OPEN','TP','SL','STRUCTURAL_EXIT','EXPIRED')), direction text not null check(direction in ('BUY','SELL')), entry numeric not null, exit_price numeric, realized_move numeric, realized_pips numeric, opened_at timestamptz not null default now(), closed_at timestamptz, source text not null default 'SmartVibe outcome engine', evidence jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
alter table public.smartvibe_signal_outcomes enable row level security;
drop policy if exists "signal outcomes readable" on public.smartvibe_signal_outcomes;
create policy "signal outcomes readable" on public.smartvibe_signal_outcomes for select using(true);
create index if not exists smartvibe_signal_outcomes_status_idx on public.smartvibe_signal_outcomes(status,closed_at);
create index if not exists smartvibe_signal_outcomes_closed_idx on public.smartvibe_signal_outcomes(closed_at);
create or replace view public.smartvibe_performance_stats as select count(*) filter(where status in ('TP','SL','STRUCTURAL_EXIT')) as closed_signals,count(*) filter(where status='TP') as wins,count(*) filter(where status in ('SL','STRUCTURAL_EXIT')) as losses,coalesce(round(100.0*count(*) filter(where status='TP')/nullif(count(*) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0),2),0) as win_rate,coalesce(sum(realized_pips) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0) as realized_pips from public.smartvibe_signal_outcomes;
create or replace view public.smartvibe_period_performance as select period,period_start,closed_signals,wins,losses,win_rate,realized_pips from (select 'WEEK'::text period,date_trunc('week',closed_at) period_start,count(*) closed_signals,count(*) filter(where status='TP') wins,count(*) filter(where status in ('SL','STRUCTURAL_EXIT')) losses,coalesce(round(100.0*count(*) filter(where status='TP')/nullif(count(*) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0),2),0) win_rate,coalesce(sum(realized_pips) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0) realized_pips from public.smartvibe_signal_outcomes where closed_at is not null group by 1,2 union all select 'MONTH',date_trunc('month',closed_at),count(*),count(*) filter(where status='TP'),count(*) filter(where status in ('SL','STRUCTURAL_EXIT')),coalesce(round(100.0*count(*) filter(where status='TP')/nullif(count(*) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0),2),0),coalesce(sum(realized_pips) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0) from public.smartvibe_signal_outcomes where closed_at is not null group by 1,2 union all select 'YEAR',date_trunc('year',closed_at),count(*),count(*) filter(where status='TP'),count(*) filter(where status in ('SL','STRUCTURAL_EXIT')),coalesce(round(100.0*count(*) filter(where status='TP')/nullif(count(*) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0),2),0),coalesce(sum(realized_pips) filter(where status in ('TP','SL','STRUCTURAL_EXIT')),0) from public.smartvibe_signal_outcomes where closed_at is not null group by 1,2) q;
revoke all on public.smartvibe_performance_stats from anon,authenticated;
revoke all on public.smartvibe_period_performance from anon,authenticated;
